    }

    int rowSpace = (int)RowSpace.Value;
    int columnSpace = (int)ColumnSpace.Value;
    for (int i = 0; i < StyledGrid.Items.Count; i++)
    {
      if (StyledGrid.ContainerFromIndex(i) is not GridViewItem item)
