        continue;
      }

      Thickness NewMargin = item.Margin;
      NewMargin.Left = columnSpace;
      NewMargin.Top = rowSpace;
      NewMargin.Right = columnSpace;
      NewMargin.Bottom = rowSpace;

      item.Margin = NewMargin;
    }
  }

